<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {api,errorText} from '../../api/zenflow/client';
type Slogan={zh:string;en:string;enabled:boolean};const items=ref<Slogan[]>([]),version=ref(0),busy=ref(false);
async function load(){busy.value=true;try{const r=(await api.get('/home-slogans')).data;items.value=r.items;version.value=r.version;}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function save(){if(items.value.some(x=>!x.zh.trim())){ElMessage.warning('请填写每条中文标语');return;}busy.value=true;try{const r=(await api.put('/home-slogans',{expectedVersion:version.value,items:items.value})).data;items.value=r.items;version.value=r.version;ElMessage.success('已保存，首页将在下次进入或刷新配置时更新');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
function move(i:number,d:number){const j=i+d;if(j<0||j>=items.value.length)return;[items.value[i],items.value[j]]=[items.value[j],items.value[i]];}
onMounted(load);
</script>
<template><section v-loading="busy"><div class="page-heading"><div><div class="eyebrow">HOME WORDS</div><h1>首页标语库</h1><p class="muted">按列表顺序缓慢轮播，每条约10秒。只呈现启用的标语；全部停用时显示默认“不必着急。”</p></div><el-button type="primary" :disabled="busy" @click="save">保存标语库</el-button></div><div class="toolbar"><el-button :disabled="items.length>=100||busy" @click="items.push({zh:'',en:'',enabled:true})">新增标语</el-button><el-button :disabled="busy" @click="load">重新加载</el-button></div><article v-for="(item,i) in items" :key="i" class="model-card" style="margin-top:16px"><div style="display:flex;gap:12px;align-items:center"><strong>{{i+1}}</strong><el-switch v-model="item.enabled" active-text="启用"/><el-button :disabled="i===0" @click="move(i,-1)">上移</el-button><el-button :disabled="i===items.length-1" @click="move(i,1)">下移</el-button><el-button type="danger" text @click="items.splice(i,1)">删除</el-button></div><el-input v-model="item.zh" maxlength="80" show-word-limit placeholder="中文标语，例如：让万物穿过自己。" style="margin-top:14px"/><el-input v-model="item.en" maxlength="140" show-word-limit placeholder="英文（可选；未填写时英文首页显示中文原句）" style="margin-top:10px"/></article><p v-if="!items.length" class="muted">暂无自定义标语，首页使用默认文案。</p><p class="muted">编辑、排序和删除在保存后生效。请维护自己的文案；引用他人原文时核对出处。</p></section></template>
